#!/usr/bin/env python3
"""FS3 v187 - Silvio's points on v186.

    Bar         The lives icon is back in front of the count. The chosen
                secondary bank is marked in the theme's own glow, not a
                fixed orange (it read red on Void).
    Rearm       SEEKING reads LOCK / NEAREST / STRAIGHT.
    Arsenal     Lamprey, Hornet, Piranha and Helios are out. Default
                Hornets became Tornados, default Piranhas Infyrnos.
    Infyrno     As in weapons.tbl: it lets go 14 "Cluster Bomb Baby"
                heat seekers (35 each, 250 m/s, 0.3 s), on the second
                press, on impact, or at the end of its flight.
    Missiles    The player's and the escorts' missiles point where they
                fly; the trail stays behind them.
    Sounds      The player's FS2 weapons use their FS2 sounds (files under
                their FS2 names in sounds/): L_Prom_R, L_Sidearm, m_shrike
                and so on, hit_1 on a primary impact, boom_2 on a missile
                impact, clusterboom when an Infyrno goes off. The AI keeps
                the old ones until its own step.

Needs v186. Edits src/ in place and writes the updated simulations. Run
assemble.py afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/56_banks.js"):
    sys.exit("Abbruch: erst v186 einspielen.")
if "CLUSTER_CHILD" in open("src/60_effects.js", encoding="utf-8").read():
    sys.exit("Abbruch: v187 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
rep('src/12_audio.js',
    '  // The lasers of Shivan fighters and bombers.\n  wpn_shivan_light: "@@FS3_SOUND:sounds/wpn_shivan_light.mp3@@",\n  wpn_shivan_heavy: "@@FS3_SOUND:sounds/wpn_shivan_heavy.mp3@@",\n  wpn_shivan_mega: "@@FS3_SOUND:sounds/wpn_shivan_mega.mp3@@"\n};\n\n// ── The mix ──\n',
    '  // The lasers of Shivan fighters and bombers.\n  wpn_shivan_light: "@@FS3_SOUND:sounds/wpn_shivan_light.mp3@@",\n  wpn_shivan_heavy: "@@FS3_SOUND:sounds/wpn_shivan_heavy.mp3@@",\n  wpn_shivan_mega: "@@FS3_SOUND:sounds/wpn_shivan_mega.mp3@@",\n  // The player\'s FS2 arsenal (v187), files under their FS2 names (Silvio).\n  // Keys must not end in a digit: that would make them variants of one.\n  L_Prom_R: "@@FS3_SOUND:sounds/L_Prom_R.mp3@@",\n  L_Prom_S: "@@FS3_SOUND:sounds/L_Prom_S.mp3@@",\n  L_Sidearm: "@@FS3_SOUND:sounds/L_Sidearm.mp3@@",\n  L_Scalpel: "@@FS3_SOUND:sounds/L_Scalpel.mp3@@",\n  L_Flail: "@@FS3_SOUND:sounds/L_Flail2.mp3@@",\n  L_Kayser: "@@FS3_SOUND:sounds/L_Kayser.mp3@@",\n  L_Circle: "@@FS3_SOUND:sounds/L_Circle.mp3@@",\n  L_Newton: "@@FS3_SOUND:sounds/L_Newton.mp3@@",\n  m_shrike: "@@FS3_SOUND:sounds/m_shrike.mp3@@",\n  m_wasp: "@@FS3_SOUND:sounds/m_wasp.mp3@@",\n  m_fury: "@@FS3_SOUND:sounds/m_fury.mp3@@",\n  m_swarm: "@@FS3_SOUND:sounds/m_swarm.mp3@@",\n  m_angel: "@@FS3_SOUND:sounds/m_angel.mp3@@",\n  m_cluster: "@@FS3_SOUND:sounds/m_cluster.mp3@@",\n  m_stiletto: "@@FS3_SOUND:sounds/m_stiletto.mp3@@",\n  m_emp: "@@FS3_SOUND:sounds/m_emp.mp3@@",\n  m_tsunami: "@@FS3_SOUND:sounds/m_tsunami.mp3@@",\n  fs_hit: "@@FS3_SOUND:sounds/hit_1.mp3@@",        // impact of every primary\n  fs_boom: "@@FS3_SOUND:sounds/boom_2.mp3@@",      // impact of a missile\n  clusterboom: "@@FS3_SOUND:sounds/clusterboom.mp3@@"  // Infyrno going off\n};\n\n// ── The mix ──\n')
